insert into public.cartes (id, nom, gamme, dates, lieu, region, epoque, rarete, finition, description, image, ordre)
values
  ('zeus', 'Zeus', 'mythologie', 'Mythologie grecque', 'Mont Olympe, Grèce', 'europe', 'antiquite', 'mythique', 'normale', 'Roi des dieux de l''Olympe dans la mythologie grecque, maître du ciel et de la foudre. Père de nombreux dieux et héros.', null, 1),
  ('anubis', 'Anubis', 'mythologie', 'Mythologie égyptienne', 'Égypte ancienne', 'afrique', 'antiquite', 'mythique', 'normale', 'Dieu funéraire de l''Égypte ancienne, figuré avec une tête de chacal. Il préside à l''embaumement et à la pesée du cœur des défunts.', null, 2),
  ('ishtar', 'Ishtar', 'mythologie', 'Mythologie mésopotamienne', 'Mésopotamie', 'moyen-orient', 'antiquite', 'mythique', 'normale', 'Déesse mésopotamienne de l''amour et de la guerre, associée à la planète Vénus. Elle était vénérée à Babylone, notamment à la porte d''Ishtar.', null, 3),
  ('nuwa', 'Nüwa', 'mythologie', 'Mythologie chinoise', 'Chine', 'asie', 'antiquite', 'mythique', 'normale', 'Déesse créatrice de la mythologie chinoise. La tradition lui attribue la création de l''humanité et la réparation du ciel après une catastrophe.', null, 4),
  ('quetzalcoatl', 'Quetzalcóatl', 'mythologie', 'Mythologie mésoaméricaine', 'Mésoamérique', 'ameriques', 'antiquite', 'mythique', 'normale', 'Le « serpent à plumes », divinité majeure de la Mésoamérique. Associé au vent, à la connaissance et à l''étoile du matin, vénéré par les Aztèques.', null, 5),
  ('maui', 'Māui', 'mythologie', 'Mythologie polynésienne', 'Polynésie', 'oceanie', 'antiquite', 'mythique', 'normale', 'Demi-dieu et héros espiègle de la mythologie polynésienne. De nombreux récits lui attribuent la pêche des îles et la capture du soleil.', null, 6),
  ('alexandre', 'Alexandre le Grand', 'personnage', '356 – 323 av. J.-C.', 'Macédoine', 'europe', 'antiquite', 'legendaire', 'normale', 'Roi de Macédoine à vingt ans. Ses campagnes renversent l''Empire perse achéménide et étendent son pouvoir de la Grèce à la vallée de l''Indus.', 'images/alexandre.webp', 7),
  ('cesar', 'Jules César', 'personnage', '100 – 44 av. J.-C.', 'Rome', 'europe', 'antiquite', 'legendaire', 'normale', 'Général et homme politique romain. Il conquiert la Gaule, remporte la guerre civile et devient dictateur. Il est assassiné lors d''une séance du Sénat.', 'images/cesar.webp', 8),
  ('confucius', 'Confucius', 'personnage', '551 – 479 av. J.-C.', 'État de Lu, Chine', 'asie', 'antiquite', 'legendaire', 'normale', 'Penseur et enseignant. Ses paroles, rassemblées par ses disciples dans les Entretiens, ont durablement influencé la morale et l''administration en Asie de l''Est.', null, 9),
  ('qin-shi-huang', 'Qin Shi Huang', 'personnage', '259 – 210 av. J.-C.', 'Chine', 'asie', 'antiquite', 'legendaire', 'normale', 'Premier empereur de la Chine unifiée en 221 av. J.-C. Il standardise l''écriture, la monnaie et les mesures. Son tombeau est gardé par l''armée de terre cuite.', null, 10),
  ('cleopatre', 'Cléopâtre VII', 'personnage', '69 – 30 av. J.-C.', 'Alexandrie, Égypte', 'afrique', 'antiquite', 'legendaire', 'normale', 'Dernière souveraine de la dynastie lagide. Alliée à César puis à Marc Antoine, elle meurt après la défaite face à Octavien ; l''Égypte devient province romaine.', 'images/cleopatre.webp', 11),
  ('bouddha', 'Siddhartha Gautama', 'personnage', 'Ve s. av. J.-C. (dates débattues)', 'Plaine du Gange', 'asie', 'antiquite', 'legendaire', 'normale', 'Connu comme le Bouddha. Les enseignements qui lui sont attribués sont à l''origine du bouddhisme, qui s''est diffusé dans une grande partie de l''Asie.', null, 12),
  ('ashoka', 'Ashoka', 'personnage', 'v. 304 – 232 av. J.-C.', 'Empire maurya, Inde', 'asie', 'antiquite', 'epique', 'normale', 'Empereur maurya. Après la sanglante conquête du Kalinga, il soutient le bouddhisme et fait graver ses édits sur des rochers et des piliers de tout l''empire.', null, 13),
  ('hannibal', 'Hannibal Barca', 'personnage', '247 – 183 av. J.-C.', 'Carthage', 'afrique', 'antiquite', 'epique', 'normale', 'Général carthaginois de la deuxième guerre punique. Il franchit les Alpes avec son armée en 218 av. J.-C. et écrase les Romains à Cannes en 216.', null, 14),
  ('ramses-ii', 'Ramsès II', 'personnage', 'v. 1303 – 1213 av. J.-C.', 'Égypte', 'afrique', 'antiquite', 'epique', 'normale', 'Pharaon de la XIXe dynastie, au règne de plus de soixante ans. Il combat les Hittites à Qadesh puis conclut avec eux l''un des plus anciens traités de paix connus.', null, 15),
  ('cyrus-ii', 'Cyrus II', 'personnage', 'v. 600 – 530 av. J.-C.', 'Perse', 'moyen-orient', 'antiquite', 'epique', 'normale', 'Fondateur de l''Empire perse achéménide. Il soumet la Médie, la Lydie puis Babylone en 539 av. J.-C., formant le plus vaste empire de son temps.', null, 16),
  ('aristote', 'Aristote', 'personnage', '384 – 322 av. J.-C.', 'Grèce', 'europe', 'antiquite', 'epique', 'normale', 'Philosophe, élève de Platon et précepteur d''Alexandre. Ses travaux couvrent la logique, la physique, la biologie, l''éthique et la politique.', null, 17),
  ('hammurabi', 'Hammurabi', 'personnage', 'règne v. 1792 – 1750 av. J.-C.', 'Babylone', 'moyen-orient', 'antiquite', 'epique', 'normale', 'Roi de Babylone, unificateur de la Mésopotamie. Son recueil de près de 300 lois, gravé sur une stèle de basalte, est conservé au musée du Louvre.', null, 18),
  ('archimede', 'Archimède', 'personnage', 'v. 287 – 212 av. J.-C.', 'Syracuse, Sicile', 'europe', 'antiquite', 'epique', 'normale', 'Mathématicien, physicien et ingénieur, connu pour son principe sur les corps plongés dans un fluide. Il meurt lors de la prise de Syracuse par Rome.', 'images/archimede.webp', 19),
  ('pericles', 'Périclès', 'personnage', 'v. 495 – 429 av. J.-C.', 'Athènes', 'europe', 'antiquite', 'rare', 'normale', 'Homme d''État athénien, stratège pendant une trentaine d''années. Il fait bâtir le Parthénon et meurt de l''épidémie qui frappe Athènes en 429 av. J.-C.', null, 20),
  ('sun-tzu', 'Sun Tzu', 'personnage', 'VIe – Ve s. av. J.-C.', 'Chine', 'asie', 'antiquite', 'rare', 'normale', 'Stratège à qui la tradition attribue L''Art de la guerre, traité militaire encore étudié aujourd''hui. Son existence historique reste discutée.', null, 21),
  ('spartacus', 'Spartacus', 'personnage', 'v. 103 – 71 av. J.-C.', 'Italie romaine', 'europe', 'antiquite', 'rare', 'normale', 'Gladiateur d''origine thrace. Il mène la plus grande révolte d''esclaves de la République romaine, réprimée par Crassus en 71 av. J.-C.', null, 22),
  ('boudicca', 'Boudicca', 'personnage', 'morte v. 61 apr. J.-C.', 'Bretagne romaine', 'europe', 'antiquite', 'rare', 'normale', 'Reine des Icènes, peuple de l''est de l''actuelle Angleterre. Elle conduit un soulèvement contre l''occupation romaine, finalement vaincu.', null, 23),
  ('vercingetorix', 'Vercingétorix', 'personnage', 'v. 82 – 46 av. J.-C.', 'Gaule', 'europe', 'antiquite', 'rare', 'normale', 'Chef arverne qui fédère des peuples gaulois contre César. Assiégé à Alésia en 52 av. J.-C., il se rend ; il est exécuté à Rome six ans plus tard.', null, 24),
  ('hatchepsout', 'Hatchepsout', 'personnage', 'règne v. 1479 – 1458 av. J.-C.', 'Égypte', 'afrique', 'antiquite', 'rare', 'normale', 'Pharaonne de la XVIIIe dynastie. Son règne est marqué par de grands chantiers, dont le temple de Deir el-Bahari, et une expédition vers le pays de Pount.', null, 25),
  ('piye', 'Piye', 'personnage', 'règne v. 744 – 714 av. J.-C.', 'Royaume de Koush (Soudan)', 'afrique', 'antiquite', 'rare', 'normale', 'Roi de Koush, État de la vallée du Nil au sud de l''Égypte. Il conquiert l''Égypte et fonde la XXVe dynastie, dite koushite.', null, 26),
  ('chandragupta', 'Chandragupta Maurya', 'personnage', 'v. 340 – 297 av. J.-C.', 'Inde', 'asie', 'antiquite', 'rare', 'normale', 'Fondateur de l''Empire maurya, premier État à unifier la majeure partie du sous-continent indien. Il est le grand-père d''Ashoka.', null, 27),
  ('nabuchodonosor', 'Nabuchodonosor II', 'personnage', 'v. 634 – 562 av. J.-C.', 'Babylone', 'moyen-orient', 'antiquite', 'rare', 'normale', 'Roi de Babylone. Il embellit sa capitale, notamment la porte d''Ishtar, et prend Jérusalem en 587 av. J.-C., déportant une partie de sa population.', null, 28),
  ('zenobie', 'Zénobie', 'personnage', 'v. 240 – après 274', 'Palmyre, Syrie', 'moyen-orient', 'antiquite', 'rare', 'normale', 'Reine de Palmyre. Au nom de son fils, elle étend son autorité sur l''Égypte et une partie de l''Anatolie avant d''être vaincue par l''empereur Aurélien en 272.', null, 29),
  ('sappho', 'Sappho', 'personnage', 'v. 630 – 570 av. J.-C.', 'Lesbos, Grèce', 'europe', 'antiquite', 'ordinaire', 'normale', 'Poétesse lyrique. Son œuvre, très admirée dans l''Antiquité, ne nous est parvenue que par fragments.', null, 30),
  ('herodote', 'Hérodote', 'personnage', 'v. 484 – 425 av. J.-C.', 'Halicarnasse, Anatolie', 'moyen-orient', 'antiquite', 'ordinaire', 'normale', 'Auteur des Histoires, récit des guerres médiques entre Grecs et Perses. Cicéron le surnomme « le père de l''histoire ».', null, 31),
  ('hypatie', 'Hypatie', 'personnage', 'v. 360 – 415 apr. J.-C.', 'Alexandrie, Égypte', 'afrique', 'antiquite', 'ordinaire', 'normale', 'Mathématicienne, astronome et philosophe néoplatonicienne. Elle enseigne à Alexandrie, où elle est tuée par une foule en 415.', null, 32),
  ('zhang-qian', 'Zhang Qian', 'personnage', 'mort en 113 av. J.-C.', 'Chine', 'asie', 'antiquite', 'ordinaire', 'normale', 'Diplomate de la dynastie Han. Ses missions vers l''Asie centrale ouvrent des contacts réguliers qui préfigurent les routes de la soie.', null, 33),
  ('ban-zhao', 'Ban Zhao', 'personnage', 'v. 45 – 117 apr. J.-C.', 'Chine', 'asie', 'antiquite', 'ordinaire', 'normale', 'Historienne et lettrée. Elle achève le Livre des Han, histoire officielle de la dynastie, commencé par son père et son frère.', null, 34),
  ('ezana', 'Ézana', 'personnage', 'IVe s. apr. J.-C.', 'Aksoum (Éthiopie)', 'afrique', 'antiquite', 'ordinaire', 'normale', 'Roi d''Aksoum, puissance commerciale de la mer Rouge. Il adopte le christianisme vers 330, comme en témoignent ses inscriptions et ses monnaies.', null, 35),
  ('imhotep', 'Imhotep', 'personnage', 'XXVIIe s. av. J.-C.', 'Égypte', 'afrique', 'antiquite', 'ordinaire', 'normale', 'Haut dignitaire du pharaon Djéser, à qui l''on attribue la conception de la pyramide à degrés de Saqqarah. Il est divinisé bien après sa mort.', null, 36),
  ('siyaj-kak', 'Siyaj K''ak''', 'personnage', 'actif v. 378 apr. J.-C.', 'Tikal (Guatemala)', 'ameriques', 'antiquite', 'ordinaire', 'normale', 'Personnage lié à Teotihuacan. Selon les inscriptions mayas, son arrivée à Tikal en 378 coïncide avec un changement de dynastie.', null, 37),
  ('yax-kuk-mo', 'K''inich Yax K''uk'' Mo''', 'personnage', 'Ve s. apr. J.-C.', 'Copán (Honduras)', 'ameriques', 'antiquite', 'ordinaire', 'normale', 'Fondateur, en 426, de la dynastie qui règne sur la cité maya de Copán pendant près de quatre siècles.', null, 38),
  ('thales', 'Thalès de Milet', 'personnage', 'v. 625 – 547 av. J.-C.', 'Milet, Ionie', 'moyen-orient', 'antiquite', 'ordinaire', 'normale', 'Considéré comme l''un des premiers philosophes grecs. La tradition lui attribue des travaux de géométrie et la prédiction d''une éclipse.', null, 39),
  ('kanishka', 'Kanishka', 'personnage', 'IIe s. apr. J.-C.', 'Empire kouchan', 'asie', 'antiquite', 'ordinaire', 'normale', 'Souverain de l''Empire kouchan, de l''Asie centrale au nord de l''Inde. Il favorise le bouddhisme et l''essor de l''art du Gandhara.', null, 40),
  ('pytheas', 'Pythéas', 'personnage', 'IVe s. av. J.-C.', 'Massalia (Marseille)', 'europe', 'antiquite', 'ordinaire', 'normale', 'Navigateur et astronome grec. Il explore les côtes de l''Atlantique nord et décrit une terre lointaine qu''il nomme Thulé.', null, 41),
  ('jeanne-d-arc', 'Jeanne d''Arc', 'personnage', 'v. 1412 – 1431', 'Royaume de France', 'europe', 'moyen-age', 'legendaire', 'normale', 'Pendant la guerre de Cent Ans, cette jeune paysanne contribue à lever le siège d''Orléans en 1429 et fait sacrer Charles VII à Reims. Capturée, elle est brûlée à Rouen en 1431.', 'images/jeanne-d-arc.webp', 1)
